from pathlib import Path

APP = "RoseLauncher"
VERSION = "1.0.0"

IS_WIN = sys.platform.startswith("win")
IS_MAC = sys.platform == "darwin"
OS_NAME = "windows" if IS_WIN else ("osx" if IS_MAC else "linux")
_M = platform.machine().lower()
IS_ARM = _M in ("arm64", "aarch64")
ARCH = "x86" if _M in ("x86", "i386", "i686") else ("arm64" if IS_ARM else "x86_64")

if IS_WIN:
    ROOT = Path(os.environ.get("APPDATA") or Path.home()) / ".roselauncher"
else:
    ROOT = Path.home() / ".roselauncher"
GAME_DIR = ROOT / "game"
LIB_DIR = ROOT / "libraries"
ASSET_DIR = ROOT / "assets"
VER_DIR = ROOT / "versions"
RT_DIR = ROOT / "runtime"
LOG_DIR = ROOT / "logs"
CFG_FILE = ROOT / "config.json"
MANIFEST_CACHE = ROOT / "version_manifest.json"

MANIFEST_URL = "https://piston-meta.mojang.com/mc/game/version_manifest_v2.json"
RUNTIME_URL = ("https://launcher.mojang.com/v1/products/java-runtime/"
               "2ec0cc96c44e5a76b9c8b7c39df7210883d12871/all.json")
ASSET_URL = "https://resources.download.minecraft.net/"
MIN_RELEASE_TIME = "2018-07-17"  # 1.13 ve sonrası (yeni 'arguments' biçimi)

UA = {"User-Agent": f"{APP}/{VERSION}"}

# Discord Developer Portal'da "RoseLauncher" adıyla oluşturduğunuz uygulamanın
# Application ID'sini buraya yazabilir ya da arayüzdeki alana yapıştırabilirsiniz.
DISCORD_APP_ID = ""

BANNER_B64 = ""
FAV_B64 = ""


def log(msg):
    try:
        LOG_DIR.mkdir(parents=True, exist_ok=True)
        with open(LOG_DIR / "launcher.log", "a", encoding="utf-8") as f:
            f.write(time.strftime("%Y-%m-%d %H:%M:%S ") + str(msg) + "\n")
    except Exception:
        pass


# ----------------------------------------------------------------- ağ
def http_get(url, timeout=30, retries=3):
    last = None
    for i in range(retries):
        try:
            req = urllib.request.Request(url, headers=UA)
            with urllib.request.urlopen(req, timeout=timeout) as r:
                return r.read()
        except Exception as e:  # noqa: BLE001
            last = e
            time.sleep(1 + i)
    raise RuntimeError(f"İndirilemedi: {url} ({last})")


def get_json(url):
    return json.loads(http_get(url).decode("utf-8"))


def sha1_of(path):
    h = hashlib.sha1()
    with open(path, "rb") as f:
        for b in iter(lambda: f.read(65536), b""):
            h.update(b)
    return h.hexdigest()


def download(url, dest, sha1=None, size=None):
    dest = Path(dest)
    if dest.is_file():
        if size is not None and dest.stat().st_size == size:
            return
        if size is None and sha1 and sha1_of(dest) == sha1:
            return
    dest.parent.mkdir(parents=True, exist_ok=True)
    tmp = dest.with_name(dest.name + ".part")
    last = None
    for i in range(3):
        try:
            h = hashlib.sha1()
            with urllib.request.urlopen(urllib.request.Request(url, headers=UA), timeout=30) as r, \
                    open(tmp, "wb") as f:
                for chunk in iter(lambda: r.read(65536), b""):
                    f.write(chunk)
                    h.update(chunk)
            if sha1 and h.hexdigest() != sha1:
                raise IOError("sha1 uyuşmuyor")
            os.replace(tmp, dest)
            return
        except Exception as e:  # noqa: BLE001
            last = e
            time.sleep(1 + i)
    try:
        tmp.unlink()
    except OSError:
        pass
    raise RuntimeError(f"İndirilemedi: {url} ({last})")


# ------------------------------------------------------------- durum
PL = threading.Lock()
P = {"busy": False, "playing": False, "phase": "", "done": 0, "total": 0, "msg": "", "error": ""}


def setp(**kw):
    with PL:
        P.update(kw)


def tick():
    with PL:
        P["done"] += 1


# ------------------------------------------------------- ayarlar
def load_cfg():
    try:
        return json.loads(CFG_FILE.read_text(encoding="utf-8"))
    except Exception:  # noqa: BLE001
        return {}


def save_cfg(cfg):
    ROOT.mkdir(parents=True, exist_ok=True)
    CFG_FILE.write_text(json.dumps(cfg, ensure_ascii=False, indent=2), encoding="utf-8")



# ------------------------------------------------------------ Discord
class _Pipe:
    def __init__(self, f):
        self.f = f

    def write(self, b):
        self.f.write(b)

    def read(self, n):
        buf = b""
        while len(buf) < n:
            c = self.f.read(n - len(buf))
            if not c:
                raise EOFError("Discord bağlantısı kapandı")
            buf += c
        return buf

    def close(self):
        self.f.close()


class _Sock:
    def __init__(self, s):
        self.s = s

    def write(self, b):
        self.s.sendall(b)

    def read(self, n):
        buf = b""
        while len(buf) < n:
            c = self.s.recv(n - len(buf))
            if not c:
                raise EOFError("Discord bağlantısı kapandı")
            buf += c
        return buf

    def close(self):
        self.s.close()


class Discord:
    """Discord Rich Presence (yerel IPC). Discord kapalıysa sessizce bekler."""

    def __init__(self):
        self.cv = threading.Condition()
        self.cid = ""
        self.want = None
        self.dirty = False
        self.conn = None
        self.conn_cid = ""
        self.thread = None

    # -- genel
    def set_playing(self, cid, version):
        if not re.fullmatch(r"\d{17,20}", cid or ""):
            return
        act = {
            "details": f"Minecraft {version}",
            "state": f"{APP} ile oynuyor",
            "timestamps": {"start": int(time.time())},
            "assets": {"large_image": "logo", "large_text": APP},
        }
        with self.cv:
            self.cid, self.want, self.dirty = cid, act, True
            if not self.thread:
                self.thread = threading.Thread(target=self._run, daemon=True)
                self.thread.start()
            self.cv.notify_all()

    def clear(self):
        with self.cv:
            self.want, self.dirty = None, True
            self.cv.notify_all()

    # -- iç
    def _run(self):
        while True:
            with self.cv:
                if not self.dirty:
                    self.cv.wait(5)
                want, cid, dirty = self.want, self.cid, self.dirty
                self.dirty = False
            try:
                self._step(want, cid, dirty)
            except Exception as e:  # noqa: BLE001
                log(f"Discord: {e}")
                self._close()

    def _step(self, want, cid, dirty):
        if want is None:
            if self.conn:
                try:
                    self._send_activity(None)
                except Exception:  # noqa: BLE001
                    pass
                self._close()
            return
        if self.conn and self.conn_cid != cid:
            self._close()
        if not self.conn:
            if not self._connect(cid):
                return  # Discord kapalı: 5 sn sonra tekrar denenecek
            dirty = True
        if dirty:
            self._send_activity(want)

    def _close(self):
        c, self.conn = self.conn, None
        if c:
            try:
                c.close()
            except Exception:  # noqa: BLE001
                pass

    @staticmethod
    def _paths():
        if IS_WIN:
            return [r"\\?\pipe\discord-ipc-%d" % i for i in range(10)]
        bases, out = [], []
        for k in ("XDG_RUNTIME_DIR", "TMPDIR", "TMP", "TEMP"):
            v = os.environ.get(k)
            if v and v not in bases:
                bases.append(v)
        if "/tmp" not in bases:
            bases.append("/tmp")
        for b in bases:
            for sub in ("", "snap.discord", "app/com.discordapp.Discord"):
                for i in range(10):
                    out.append(os.path.join(b, sub, "discord-ipc-%d" % i))
        return out

    def _frame(self, op, payload):
        data = json.dumps(payload).encode("utf-8")
        return struct.pack("<II", op, len(data)) + data

    def _recv(self):
        op, ln = struct.unpack("<II", self.conn.read(8))
        body = self.conn.read(ln) if ln else b"{}"
        return op, json.loads(body.decode("utf-8", "replace"))

    def _connect(self, cid):
        for path in self._paths():
            conn = None
            try:
                if IS_WIN:
                    conn = _Pipe(open(path, "r+b", buffering=0))
                else:
                    if not os.path.exists(path):
                        continue
                    s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
                    s.settimeout(5)
                    s.connect(path)
                    conn = _Sock(s)
                self.conn = conn
                conn.write(self._frame(0, {"v": 1, "client_id": cid}))
                op, data = self._recv()
                if data.get("evt") == "READY":
                    self.conn_cid = cid
                    return True
                log(f"Discord el sıkışma yanıtı: {data}")
            except Exception:  # noqa: BLE001
                pass
            self._close()
            if conn:
                try:
                    conn.close()
                except Exception:  # noqa: BLE001
                    pass
        return False

    def _send_activity(self, act):
        self.conn.write(self._frame(1, {
            "cmd": "SET_ACTIVITY",
            "args": {"pid": os.getpid(), "activity": act},
            "nonce": str(uuid.uuid4()),
        }))
        _, data = self._recv()
        if data.get("evt") == "ERROR":
            log(f"Discord hata: {data.get('data')}")


DISCORD = Discord()

# ------------------------------------------------------ sürüm listesi
def fetch_versions():
    try:
        data = get_json(MANIFEST_URL)
        ROOT.mkdir(parents=True, exist_ok=True)
        MANIFEST_CACHE.write_text(json.dumps(data), encoding="utf-8")
    except Exception as e:  # noqa: BLE001
        log(f"manifest alınamadı: {e}")
        try:
            data = json.loads(MANIFEST_CACHE.read_text(encoding="utf-8"))
        except Exception:  # noqa: BLE001
            raise RuntimeError("Sürüm listesi alınamadı. İnternet bağlantınızı kontrol edin.")
    return [v for v in data["versions"]
            if v.get("type") == "release" and v.get("releaseTime", "") >= MIN_RELEASE_TIME]


# ------------------------------------------------------------ kurallar
def rule_matches(rule):
    if rule.get("features"):
        return False  # hiçbir özel özellik (demo, çözünürlük vb.) açık değil
    o = rule.get("os")
    if o:
        if "name" in o and o["name"] != OS_NAME:
            return False
        if "arch" in o and o["arch"] != ARCH:
            return False
        if "version" in o and not re.search(o["version"], platform.version()):
            return False
    return True


def rules_ok(rules):
    if not rules:
        return True
    allowed = False
    for r in rules:
        if rule_matches(r):
            allowed = r.get("action") == "allow"
    return allowed


# ------------------------------------------------------- kütüphaneler
def lib_plan(vj):
    cp, dl, natives = [], [], []
    for lib in vj.get("libraries", []):
        if not rules_ok(lib.get("rules")):
            continue
        d = lib.get("downloads", {})
        art = d.get("artifact")
        if art and art.get("url"):
            p = LIB_DIR / art["path"]
            dl.append((art["url"], p, art.get("sha1"), art.get("size")))
            cp.append(str(p))
        nat = lib.get("natives")
        if nat and OS_NAME in nat:
            cls = nat[OS_NAME].replace("${arch}", "32" if ARCH == "x86" else "64")
            a = d.get("classifiers", {}).get(cls)
            if a and a.get("url"):
                p = LIB_DIR / a["path"]
                dl.append((a["url"], p, a.get("sha1"), a.get("size")))
                natives.append((p, lib.get("extract", {}).get("exclude", [])))
    return cp, dl, natives


def extract_natives(items, ndir):
    ndir.mkdir(parents=True, exist_ok=True)
    base = ndir.resolve()
    for path, excl in items:
        with zipfile.ZipFile(path) as z:
            for n in z.namelist():
                if n.endswith("/") or any(n.startswith(e) for e in excl):
                    continue
                tgt = (ndir / n).resolve()
                if base not in tgt.parents:
                    continue
                tgt.parent.mkdir(parents=True, exist_ok=True)
                try:
                    with z.open(n) as s, open(tgt, "wb") as o:
                        shutil.copyfileobj(s, o)
                except PermissionError:
                    if not tgt.exists():
                        raise


# ------------------------------------------------------------- Java
def runtime_key():
    if IS_WIN:
        return "windows-arm64" if IS_ARM else ("windows-x86" if ARCH == "x86" else "windows-x64")
    if IS_MAC:
        return "mac-os-arm64" if IS_ARM else "mac-os"
    return "linux-i386" if ARCH == "x86" else "linux"


def java_bin(rdir):
    exe = "java.exe" if IS_WIN else "java"
    for cand in (rdir / "bin" / exe, rdir / "jre.bundle" / "Contents" / "Home" / "bin" / exe):
        if cand.is_file():
            return cand
    return None


def system_java(need):
    cands = []
    jh = os.environ.get("JAVA_HOME")
    if jh:
        cands.append(str(Path(jh) / "bin" / ("java.exe" if IS_WIN else "java")))
    cands.append("java")
    for c in cands:
        try:
            out = subprocess.run([c, "-version"], capture_output=True, text=True, timeout=15,
                                 creationflags=0x08000000 if IS_WIN else 0)
            m = re.search(r'version "(\d+)(?:\.(\d+))?', out.stderr + out.stdout)
            if not m:
                continue
            major = int(m.group(1))
            if major == 1:
                major = int(m.group(2) or 8)
            if major >= need:
                return c
        except Exception:  # noqa: BLE001
            continue
    return None


def ensure_java(vj):
    jv = vj.get("javaVersion", {})
    comp = jv.get("component", "jre-legacy")
    need = jv.get("majorVersion", 8)
    key = runtime_key()
    rdir = RT_DIR / comp / key / comp
    marker = RT_DIR / comp / key / ".rose_ok"
    if marker.is_file():
        j = java_bin(rdir)
        if j:
            return str(j)
    try:
        setp(phase="Java hazırlanıyor", msg=f"Java {need}", done=0, total=1)
        allj = get_json(RUNTIME_URL)
        entry = allj.get(key, {}).get(comp)
        if not entry:
            raise RuntimeError("Bu platform için Java paketi bulunamadı")
        manifest = get_json(entry[0]["manifest"]["url"])
        files = manifest["files"]
        base = rdir.resolve()
        todo = []
        for rel, info in files.items():
            tgt = (rdir / rel).resolve()
            if base != tgt and base not in tgt.parents:
                continue
            t = info.get("type")
            if t == "directory":
                tgt.mkdir(parents=True, exist_ok=True)
            elif t == "file":
                raw = info["downloads"]["raw"]
                todo.append((raw["url"], tgt, raw.get("sha1"), raw.get("size"), info.get("executable")))
        setp(total=max(len(todo), 1), done=0)

        def one(x):
            download(x[0], x[1], x[2], x[3])
            if x[4] and not IS_WIN:
                os.chmod(x[1], 0o755)
            tick()

        with ThreadPoolExecutor(8) as ex:
            list(ex.map(one, todo))
        j = java_bin(rdir)
        if not j:
            raise RuntimeError("Java dosyaları eksik indirildi")
        marker.write_text("ok")
        return str(j)
    except Exception as e:  # noqa: BLE001
        log(f"Mojang Java alınamadı, sistem Java'sı denenecek: {e}")
        j = system_java(need)
        if j:
            return j
        raise RuntimeError(f"Java {need} gerekli ve otomatik indirilemedi. "
                           f"Java {need} kurup tekrar deneyin. ({e})")


# ----------------------------------------------------------- argümanlar
def subst(s, ctx):
    return re.sub(r"\$\{(\w+)\}", lambda m: str(ctx.get(m.group(1), m.group(0))), s)


def build_args(vj, ctx, kind):
    out = []
    for a in vj.get("arguments", {}).get(kind, []):
        if isinstance(a, str):
            vals = [a]
        else:
            if not rules_ok(a.get("rules")):
                continue
            v = a.get("value")
            vals = [v] if isinstance(v, str) else list(v)
        out += [subst(x, ctx) for x in vals]
    return out


def offline_uuid(name):
    h = bytearray(hashlib.md5(("OfflinePlayer:" + name).encode("utf-8")).digest())
    h[6] = (h[6] & 0x0F) | 0x30
    h[8] = (h[8] & 0x3F) | 0x80
    return str(uuid.UUID(bytes=bytes(h)))


# ------------------------------------------------------------- kurulum
def install(vid, vinfo):
    vdir = VER_DIR / vid
    vjson = vdir / f"{vid}.json"
    ok_marker = vdir / ".rose_ok"

    setp(phase="Sürüm bilgisi", msg=vid, done=0, total=1)
    if not vjson.is_file():
        vdir.mkdir(parents=True, exist_ok=True)
        vj = get_json(vinfo["url"])
        vjson.write_text(json.dumps(vj), encoding="utf-8")
    vj = json.loads(vjson.read_text(encoding="utf-8"))

    cp, dl, natives = lib_plan(vj)
    client = vj["downloads"]["client"]
    client_jar = vdir / f"{vid}.jar"
    ndir = vdir / "natives"

    if not ok_marker.is_file():
        setp(phase="Minecraft indiriliyor", msg="İstemci", done=0, total=1)
        download(client["url"], client_jar, client.get("sha1"), client.get("size"))

        ai = vj["assetIndex"]
        idx_path = ASSET_DIR / "indexes" / f"{ai['id']}.json"
        download(ai["url"], idx_path, ai.get("sha1"), ai.get("size"))
        objects = json.loads(idx_path.read_text(encoding="utf-8"))["objects"]
        seen = {}
        for o in objects.values():
            seen[o["hash"]] = o["size"]

        jobs = [(u, p, s, z) for (u, p, s, z) in dl]
        for h, z in seen.items():
            jobs.append((f"{ASSET_URL}{h[:2]}/{h}", ASSET_DIR / "objects" / h[:2] / h, h, z))
        setp(phase="Dosyalar indiriliyor", msg="Kütüphaneler ve oyun dosyaları",
             done=0, total=len(jobs))

        def one(j):
            download(*j)
            tick()

        with ThreadPoolExecutor(12) as ex:
            list(ex.map(one, jobs))
        ok_marker.write_text("ok")

    if natives:
        extract_natives(natives, ndir)
    else:
        ndir.mkdir(parents=True, exist_ok=True)
    cp.append(str(client_jar))
    return vj, cp, ndir


def run_game(username, vid, ram_mb):
    vinfo = None
    vjson = VER_DIR / vid / f"{vid}.json"
    if not vjson.is_file():
        vers = fetch_versions()
        vinfo = next((v for v in vers if v["id"] == vid), None)
        if not vinfo:
            raise RuntimeError("Seçilen sürüm bulunamadı")
    vj, cp, ndir = install(vid, vinfo)
    java = ensure_java(vj)

    GAME_DIR.mkdir(parents=True, exist_ok=True)
    sep = ";" if IS_WIN else ":"
    seen, uniq = set(), []
    for c in cp:
        if c not in seen:
            seen.add(c)
            uniq.append(c)
    ctx = {
        "auth_player_name": username, "version_name": vid,
        "game_directory": str(GAME_DIR), "assets_root": str(ASSET_DIR),
        "assets_index_name": vj["assetIndex"]["id"], "auth_uuid": offline_uuid(username),
        "auth_access_token": "0", "clientid": "0", "auth_xuid": "0",
        "user_type": "legacy", "version_type": APP, "user_properties": "{}",
        "natives_directory": str(ndir), "launcher_name": APP, "launcher_version": VERSION,
        "classpath": sep.join(uniq), "library_directory": str(LIB_DIR),
        "classpath_separator": sep,
    }
    cmd = [java, f"-Xmx{ram_mb}M"] + build_args(vj, ctx, "jvm") \
        + [vj["mainClass"]] + build_args(vj, ctx, "game")
    log("Başlatılıyor: " + " ".join(cmd[:3]) + " ...")

    LOG_DIR.mkdir(parents=True, exist_ok=True)
    out = open(LOG_DIR / "game.log", "w", encoding="utf-8", errors="replace")
    proc = subprocess.Popen(cmd, cwd=str(GAME_DIR), stdout=out, stderr=subprocess.STDOUT,
                            creationflags=0x08000000 if IS_WIN else 0)
    setp(phase="Oyun çalışıyor", msg=f"Minecraft {vid}", done=1, total=1, playing=True)
    cfg = load_cfg()
    if cfg.get("presence", True):
        DISCORD.set_playing(cfg.get("discord_id") or DISCORD_APP_ID, vid)

    def watch():
        code = proc.wait()
        out.close()
        DISCORD.clear()
        setp(playing=False)
        if code != 0:
            setp(phase="", msg="", error=f"Oyun {code} koduyla kapandı. Kayıt: {LOG_DIR / 'game.log'}")
        else:
            setp(phase="", msg="Oyun kapandı.", error="")

    threading.Thread(target=watch, daemon=True).start()


def launch_job(username, vid, ram_mb):
    try:
        run_game(username, vid, ram_mb)
    except Exception as e:  # noqa: BLE001
        log(f"HATA: {e}")
        setp(phase="", msg="", error=str(e))
    finally:
        setp(busy=False)


